export default "CREATE TABLE IF NOT EXISTS assignments (\n    id TEXT PRIMARY KEY,\n    assignment_name VARCHAR(255) NOT NULL,\n    external_contact TEXT,\n    company TEXT,\n    fee DECIMAL(10, 2),\n    type VARCHAR(50),\n    status VARCHAR(50),\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (external_contact) REFERENCES contacts(id),\n    FOREIGN KEY (company) REFERENCES companies(id)\n);\n\nCREATE TABLE IF NOT EXISTS assignment_responsible_contacts (\n    assignment_id TEXT NOT NULL,\n    contact_id TEXT NOT NULL,\n    PRIMARY KEY (assignment_id, contact_id),\n    FOREIGN KEY (assignment_id) REFERENCES assignments(id),\n    FOREIGN KEY (contact_id) REFERENCES contacts(id)\n);\n\nCREATE TABLE IF NOT EXISTS contacts (\n    id TEXT PRIMARY KEY,\n    contact_name VARCHAR(255) NOT NULL,\n    email VARCHAR(255),\n    phone VARCHAR(20),\n    job_title VARCHAR(100),\n    company TEXT,\n    address VARCHAR(255),\n    notes TEXT,\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (company) REFERENCES companies(id)\n);\n\nCREATE TABLE IF NOT EXISTS companies (\n    id TEXT PRIMARY KEY,\n    company_name VARCHAR(255) NOT NULL,\n    address VARCHAR(255),\n    industry VARCHAR(100),\n    phone VARCHAR(20),\n    email VARCHAR(255),\n    website VARCHAR(255),\n    organization_number VARCHAR(255),\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS document_references (\n    id TEXT PRIMARY KEY,\n    document TEXT NOT NULL,\n    entity_type VARCHAR(50) NOT NULL,\n    entity_id TEXT NOT NULL,\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    UNIQUE(document, entity_type, entity_id)\n);\n\nCREATE TABLE IF NOT EXISTS interactions (\n    id TEXT PRIMARY KEY,\n    interaction_date DATE NOT NULL,\n    interaction_type VARCHAR(50) NOT NULL,\n    notes TEXT,\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS interaction_contacts (\n    interaction_id TEXT NOT NULL,\n    contact_id TEXT NOT NULL,\n    PRIMARY KEY (interaction_id, contact_id),\n    FOREIGN KEY (interaction_id) REFERENCES interactions(id),\n    FOREIGN KEY (contact_id) REFERENCES contacts(id)\n);\n\nCREATE TABLE IF NOT EXISTS leads (\n    id TEXT NOT NULL,\n    lead_title VARCHAR(255) NOT NULL,\n    description TEXT,\n    stage VARCHAR(50) NOT NULL,\n    rank INTEGER,\n    contact INTEGER,\n    company INTEGER,\n    assignment INTEGER,\n    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (contact) REFERENCES contacts(id),\n    FOREIGN KEY (company) REFERENCES companies(id),\n    FOREIGN KEY (assignment) REFERENCES assignments(id)\n);\n"