export default "CREATE TRIGGER update_assignments_updated_at\nAFTER UPDATE ON assignments\nFOR EACH ROW\nBEGIN\n    UPDATE assignments\n    SET updated_at = CURRENT_TIMESTAMP\n    WHERE id = OLD.id;\nEND;\n\nCREATE TRIGGER update_contacts_updated_at\nAFTER UPDATE ON contacts\nFOR EACH ROW\nBEGIN\n    UPDATE contacts\n    SET updated_at = CURRENT_TIMESTAMP\n    WHERE id = OLD.id;\nEND;\n\nCREATE TRIGGER update_companies_updated_at\nAFTER UPDATE ON companies\nFOR EACH ROW\nBEGIN\n    UPDATE companies\n    SET updated_at = CURRENT_TIMESTAMP\n    WHERE id = OLD.id;\nEND;\n\nCREATE TRIGGER update_document_references_updated_at\nAFTER UPDATE ON document_references\nFOR EACH ROW\nBEGIN\n    UPDATE document_references\n    SET updated_at = CURRENT_TIMESTAMP\n    WHERE document = OLD.document AND entity_type = OLD.entity_type AND entity_id = OLD.entity_id;\nEND;\n\nCREATE TRIGGER update_interactions_updated_at\nAFTER UPDATE ON interactions\nFOR EACH ROW\nBEGIN\n    UPDATE interactions\n    SET updated_at = CURRENT_TIMESTAMP\n    WHERE id = OLD.id;\nEND;\n\nCREATE TRIGGER update_leads_updated_at\nAFTER UPDATE ON leads\nFOR EACH ROW\nBEGIN\n    UPDATE leads\n    SET updated_at = CASE\n            WHEN NEW.lead_title != OLD.lead_title\n                OR NEW.stage != OLD.stage\n                OR NEW.contact != OLD.contact\n                OR NEW.company != OLD.company\n                OR NEW.assignment != OLD.assignment\n            THEN CURRENT_TIMESTAMP\n            ELSE OLD.updated_at\n        END\n    WHERE id = OLD.id;\nEND;\n"